  const nativeGet = (url, headers, responseType) => nativeCall('CapacitorHttp', 'request',
    { url, method: 'GET', headers: { 'User-Agent': APP_UA(), ...(headers || {}) }, responseType: responseType || 'blob', connectTimeout: 20000, readTimeout: 60000 });
