      pill.textContent = st === 'Open' ? ((d.reopened || []).length ? 'Open · rejected' : 'Open · to fix') : st === 'Rectified' ? 'Fixed · to check' : st === 'Verified' ? 'Accepted' : 'Note';
      const lines = [];
      if (d.notes) lines.push(d.notes);
