    peopleOf().forEach((x) => people.push([x.name, x.company, x.mobile, x.email]));
    sheets.push({ name: 'People', cols: [28, 28, 18, 32], rows: people, freezeRow: 1 }, exporterSheet(st));
    const parts = R.buildXlsxParts(sheets);
