    if (iv && !keyMode()) { S.inviteCode = iv; persist(); }
    if (co) { let c = co; try { c = decodeURIComponent(co); } catch (e) { /* as is */ } S.inviteCo = String(c).replace(/\s+/g, ' ').trim().slice(0, 100); if (!cosRaw) S.inviteCos = []; persist(); }
