  function taskJob(name) { const p = pmeta(name).purpose || 'As-plan'; return taskCat(name) === 'Survey' ? (p === 'CEF-plan' ? 'As-plan' : p) : 'acc'; } // (v2.44: a CEF-Plan is approved by the As-Plan approver)
