      const cols = (Array.isArray(t.cols) ? t.cols : []).filter((x) => Array.isArray(x) && x[0]).slice(0, 12).map((x) => [s100(x[0], 40), s100(x[1])]); // v2.41: the columns between Territory and OSP VENDOR
