        company: s100(t.company, 200), status: s100(t.status, 40) || 'Active', notes: s100(t.notes, 300), link: /^https:\/\//.test(link) ? link : '', extra, ...(cols.length ? { cols } : {}),
        region: s100(t.region, 60), territory: s100(t.territory, 60),
